INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 0, 0, 24015, 1, 0, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 24, 110501, "カオリ（サマー）", 4, 4, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 4, 0, 24016, 2, 0, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 24, 110501, "カオリ（サマー）", 1, 4, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 0, 0, 24017, 3, 0, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 24, 110501, "カオリ（サマー）", 4, 4, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 5.2, 0, 24018, 4, 0, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 24, 110501, "カオリ（サマー）", 2, 1, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 4.2, 0, 24019, 5, 0, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 24, 110501, "カオリ（サマー）", 6, 5, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 0, 0, 24020, 6, 0, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 24, 110501, "カオリ（サマー）", 2, 2, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 6.4, 0, 24021, 7, 0, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 24, 110501, "カオリ（サマー）", 6, 1, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 0, 0, 24022, 8, 0, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 24, 110501, "カオリ（サマー）", 2, 2, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 10.08, 0, 24023, 9, 0, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 24, 110501, "カオリ（サマー）", 3, 6, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 5, 0, 24024, 10, 0, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 24, 110501, "カオリ（サマー）", 2, 1, 10021);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", "2030/12/17 14:59:59", 0, 0, 24025, 11, 0, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 24, 110501, "カオリ（サマー）", 2, 2, 10021);
